class Solution(object):
    def longestSubsequence(self, arr, difference):
        """
        :type arr: List[int]
        :type difference: int
        :rtype: int
        """
        dp = collections.defaultdict(int)
        for num in arr:
            dp[num] = max(dp[num], dp[num - difference] + 1)
        return max(dp.values())

